// Generated by Copilot

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('discover-form');
  const input = document.getElementById('words-input');
  const result = document.getElementById('result');

  if (!form || !input || !result) {
    return;
  }

  const parseInputWords = (value) => value
    .split(/[\n,]+/)
    .map((word) => word.trim())
    .filter(Boolean);

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const rawValue = input.value.trim();

    if (!rawValue) {
      result.textContent = 'Please enter at least one word or clue.';
      result.classList.add('error');
      return;
    }

    try {
      const words = parseInputWords(rawValue);
      const match = window.discoverUserName(words);
      result.classList.remove('error');

      if (!match) {
        result.textContent = 'No matching name was found for those words.';
        return;
      }

      result.textContent = `Matching name: ${match}`;
    } catch (error) {
      result.textContent = error.message;
      result.classList.add('error');
    }
  });
});
